export function greenhouse(icon){return `<section class="greenhouse" aria-labelledby="greenhouse-task"><div class="greenhouse-tools"><span id="greenhouse-step">Investigation 1 of 2</span><span>${icon('search')} Look closer. Find the evidence.</span></div><div class="greenhouse-scene" id="greenhouse-scene"><img class="greenhouse-art" src="assets/greenhouse-investigation.webp" alt="A real tomato plant with green and ripe fruits beside a tank containing an aquatic plant." width="1536" height="1024"><div class="specimen-tag" id="specimen-tag">Tomato plant</div><button id="fruit-lens" class="fruit-lens" aria-label="Magnifying lens. Use arrow keys to move over a ripe tomato." aria-describedby="greenhouse-instruction"><span class="lens-glass"></span><span class="lens-handle"></span></button><div class="fruit-marker" aria-hidden="true"></div><div id="gas-apparatus" class="gas-apparatus" hidden><button type="button" class="collector-tube" id="collector-tube" role="slider" aria-label="Collecting tube" aria-valuemin="55" aria-valuemax="93" aria-valuenow="90" aria-orientation="horizontal" aria-describedby="tube-hint"><span id="collected-gas" class="collected-gas"></span><span class="tube-marks" aria-hidden="true"></span></button><div class="rising-bubbles" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="collection-meter" id="gas-label" hidden><span id="gas-name">Oxygen</span></div></div></div><div class="greenhouse-work"><div class="greenhouse-prompt"><h2 id="greenhouse-task">There’s more than leaves here.</h2><p id="greenhouse-instruction">Slide the magnifying lens over a ripe red tomato. Hold it there to look closer.</p><p id="lens-help" class="greenhouse-hint">Drag the lens, or focus it and use the arrow keys.</p><div id="tube-control" hidden><p><strong>Drag the tube above the rising bubbles.</strong></p><p id="tube-hint" class="greenhouse-hint">Drag the tube itself left or right. Or focus it and use the left and right arrow keys.</p></div><p id="investigation-status" role="status" aria-live="polite"></p></div><div id="greenhouse-finding" class="greenhouse-finding" hidden></div></div><div id="greenhouse-conclusion" class="greenhouse-conclusion" hidden><h2>One process. Two discoveries.</h2><p>Plants make glucose during photosynthesis. Some of that food can be stored as <strong>starch</strong>. They also release <strong>oxygen</strong>.</p><button id="greenhouse-replay" class="text-btn">Explore the greenhouse again</button></div></section><p class="caption">An illustrated greenhouse investigation. Explore each plant, then read the explanation of what you observed. Science Year 4 · printed page 78.</p>`}

export function bindGreenhouse(onComplete){
 const $=s=>document.querySelector(s),scene=$('#greenhouse-scene'),lens=$('#fruit-lens'),finding=$('#greenhouse-finding'),status=$('#investigation-status');
 let phase='fruit',x=15,y=60,tubeX=90,held=0,last=performance.now(),raf=0,gasFill=0,dead=false;
 // Coordinates match the ripe fruit and the top of the aquatic plant in the illustration.
 const fruit={x:30,y:47},bubbleX=76;
 function placeLens(){lens.style.left=x+'%';lens.style.top=y+'%';const glass=lens.querySelector('.lens-glass');const r=scene.getBoundingClientRect(),diameter=lens.getBoundingClientRect().width;glass.style.backgroundSize=`${r.width*1.8}px ${r.height*1.8}px`;glass.style.backgroundPosition=`${diameter/2-x/100*r.width*1.8}px ${diameter/2-y/100*r.height*1.8}px`}
 function move(px,py){x=Math.max(8,Math.min(48,px));y=Math.max(15,Math.min(78,py));placeLens()}
 function bindDrag(element,position,apply,enabled){
  let pointer=null,offsetX=0,offsetY=0;
  element.onpointerdown=e=>{if(!enabled()||!e.isPrimary||e.button!==0)return;const r=scene.getBoundingClientRect(),pos=position();offsetX=(e.clientX-r.left)/r.width*100-pos.x;offsetY=(e.clientY-r.top)/r.height*100-pos.y;pointer=e.pointerId;element.setPointerCapture(pointer);element.focus({preventScroll:true});e.preventDefault()};
  element.onpointermove=e=>{if(e.pointerId!==pointer||!enabled())return;const r=scene.getBoundingClientRect();apply((e.clientX-r.left)/r.width*100-offsetX,(e.clientY-r.top)/r.height*100-offsetY)};
  const release=e=>{if(e.pointerId!==pointer)return;pointer=null;if(element.hasPointerCapture(e.pointerId))element.releasePointerCapture(e.pointerId)};
  element.onpointerup=element.onpointercancel=element.onlostpointercapture=release;
 }
 bindDrag(lens,()=>({x,y}),move,()=>phase==='fruit');
 lens.onkeydown=e=>{const directions={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]};if(phase==='fruit'&&directions[e.key]){e.preventDefault();const [dx,dy]=directions[e.key];move(x+dx,y+dy)}};
 function fruitFound(){phase='fruit-found';scene.classList.add('fruit-found');lens.hidden=true;$('#lens-help').hidden=true;$('#greenhouse-task').textContent='A fruit growing on the plant.';$('#greenhouse-instruction').textContent='The plant uses food it makes to grow, including growing its fruits.';status.textContent='Look closer: the explanation connects this fruit to the food made by the plant.';finding.hidden=false;finding.innerHTML='<h3>The plant made its own food.</h3><p>During photosynthesis, plants make a sugar called <strong>glucose</strong>. This food helps the plant grow and develop fruits.</p><p>Plants can also store some of this food as <strong>starch</strong> in their parts.</p><p class="finding-note">The fruit uses the plant’s food.</p><button id="investigate-tank" class="btn yellow">Investigate the water tank <span aria-hidden="true">→</span></button>';$('#investigate-tank').onclick=enterTank}
 function enterTank(){phase='gas';scene.classList.add('tank-active');$('#greenhouse-step').textContent='Investigation 2 of 2';$('#specimen-tag').textContent='Aquatic plant';$('#gas-apparatus').hidden=false;$('#tube-control').hidden=false;finding.hidden=true;finding.innerHTML='';$('#greenhouse-task').textContent='Something is escaping.';$('#greenhouse-instruction').textContent='Watch the bubbles rising from the underwater plant. Can you catch them in the tube?';status.textContent='The tube is beside the bubbles. Move it over them.';$('#collector-tube').focus({preventScroll:true})}
 const tube=$('#collector-tube');
 function placeTube(){tube.style.left=tubeX+'%';tube.setAttribute('aria-valuenow',String(Math.round(tubeX)));tube.setAttribute('aria-valuetext',tubeX<71?'Tube left of the bubbles':tubeX>81?'Tube right of the bubbles':'Tube above the bubbles')}
 function moveTube(value){tubeX=Math.max(55,Math.min(93,value));placeTube()}
 bindDrag(tube,()=>({x:tubeX,y:47}),moveTube,()=>phase==='gas');
 tube.onkeydown=e=>{if(phase!=='gas')return;if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();moveTube(e.key==='Home'?55:e.key==='End'?93:tubeX+(e.key==='ArrowLeft'?-1:1))}};

 function gasFound(){phase='done';$('#gas-label').hidden=false;$('#tube-control').hidden=true;$('#greenhouse-task').textContent='You collected a gas.';$('#greenhouse-instruction').textContent='The gas pocket grew as bubbles entered the tube.';status.textContent='The plant released gas into your tube.';finding.hidden=false;finding.innerHTML='<h3>The gas is oxygen.</h3><p>During photosynthesis, the aquatic plant releases <strong>oxygen</strong>. You collected some of that gas in the tube.</p>';$('#greenhouse-conclusion').hidden=false;onComplete()}
 function tick(now){if(dead)return;const dt=Math.min((now-last)/1000,.05);last=now;const visible=!document.hidden&&scene.getBoundingClientRect().bottom>0&&scene.getBoundingClientRect().top<innerHeight;if(visible&&phase==='fruit'){const near=Math.abs(x-fruit.x)<7&&Math.abs(y-fruit.y)<8;held=near?held+dt:0;lens.classList.toggle('is-focused',near);if(held>.7)fruitFound()}if(visible&&phase==='gas'){const aligned=Math.abs(tubeX-bubbleX)<=5;scene.classList.toggle('tube-aligned',aligned);if(aligned){gasFill=Math.min(1,gasFill+dt/4.5);$('#collected-gas').style.clipPath=`inset(0 0 ${100-gasFill*100}% 0)`;const message='The gas pocket is growing. Keep the tube here.';if(status.textContent!==message)status.textContent=message;if(gasFill===1)gasFound()}}raf=requestAnimationFrame(tick)}
 $('#greenhouse-replay').onclick=()=>{phase='fruit';x=15;y=60;held=0;gasFill=0;scene.classList.remove('tank-active','fruit-found','tube-aligned');lens.hidden=false;$('#lens-help').hidden=false;$('#gas-apparatus').hidden=true;$('#tube-control').hidden=true;$('#gas-label').hidden=true;$('#collected-gas').style.clipPath='inset(0 0 100% 0)';tubeX=90;finding.hidden=true;finding.innerHTML='';$('#greenhouse-conclusion').hidden=true;$('#greenhouse-step').textContent='Investigation 1 of 2';$('#specimen-tag').textContent='Tomato plant';$('#greenhouse-task').textContent='There’s more than leaves here.';$('#greenhouse-instruction').textContent='Slide the magnifying lens over a ripe red tomato. Hold it there to look closer.';status.textContent='';placeLens();placeTube();lens.focus()};
 const resize=new ResizeObserver(placeLens);resize.observe(scene);placeLens();placeTube();raf=requestAnimationFrame(tick);
 return ()=>{dead=true;cancelAnimationFrame(raf);resize.disconnect()};
}
